$root=dirname(__DIR__);require $root.'/global/config.php';session_set_save_handler(fn()=>true,fn()=>true,fn($id)=>'',fn($id,$data)=>true,fn($id)=>true,fn($max)=>0);app_start_session();require $root.'/global/connection.php';
$userId=(int)$pdo->query('SELECT id FROM tbl_user ORDER BY id LIMIT 1')->fetchColumn();$warehouseId=(int)$pdo->query('SELECT id FROM tbl_warehouse WHERE active_status=1 ORDER BY id LIMIT 1')->fetchColumn();$_SESSION['loggedInUser']=['USERID'=>$userId,'ROLE_CODE'=>'admin','PERMISSIONS'=>[]];
$customerId=$productId=$quotationId=$cancelledOrderId=null;$ruc='20'.str_pad((string)random_int(1,999999999),9,'0',STR_PAD_LEFT);$suffix=substr(uniqid(),-8);
function cleanupQuotationConversion(PDO $pdo,?int $quotationId,?int $productId,?int $customerId):void{if($quotationId){$orders=$pdo->prepare('SELECT id FROM tbl_sales_order WHERE quotation_id=?');$orders->execute([$quotationId]);$ids=$orders->fetchAll(PDO::FETCH_COLUMN);foreach($ids as $id){$pdo->prepare("DELETE FROM tbl_custom_field_value WHERE entity='sales_order' AND record_id=?")->execute([$id]);$pdo->prepare("DELETE FROM tbl_document_status_history WHERE document_type='sales_order' AND document_id=?")->execute([$id]);$pdo->prepare("DELETE FROM tbl_document_flow WHERE (source_type='quotation' AND source_id=?) OR (target_type='sales_order' AND target_id=?)")->execute([$quotationId,$id]);$pdo->prepare("DELETE FROM tbl_document_line_application WHERE target_type='sales_order' AND target_id=?")->execute([$id]);$pdo->prepare('DELETE FROM tbl_sales_order_detail WHERE sales_order_id=?')->execute([$id]);$pdo->prepare('DELETE FROM tbl_sales_order WHERE id=?')->execute([$id]);}$pdo->prepare('DELETE FROM tbl_quotation_detail WHERE quotation_id=?')->execute([$quotationId]);$pdo->prepare('DELETE FROM tbl_quotation WHERE id=?')->execute([$quotationId]);}if($productId)$pdo->prepare('DELETE FROM tbl_product WHERE id=?')->execute([$productId]);if($customerId)$pdo->prepare('DELETE FROM tbl_customer WHERE client_id=?')->execute([$customerId]);}
try{
 $pdo->prepare('INSERT INTO tbl_customer(ruc,business_name,trade_name,email,phone,cellphone,address,department_id,province_id,district_id,contact1_name,contact1_phone,contact2_name,contact2_phone,commission) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$ruc,'CLIENTE QA CONVERSION','QA','','','','Fiscal QA','15','1501','150101','','','','',0]);$customerId=(int)$pdo->lastInsertId();
 $code='QA-CONV-'.$suffix;$pdo->prepare('INSERT INTO tbl_product(code,brand,name,description,stock_quantity,unit_price,unit_value,active_status) VALUES(?,?,?,?,?,?,?,1)')->execute([$code,'APPU','ARTICULO QA CONVERSION','Temporal',10,25,'UND']);$productId=(int)$pdo->lastInsertId();$today=date('Y-m-d');
 $pdo->prepare("INSERT INTO tbl_quotation(number,status,customer_id,warehouse_id,ruc,name,address,shipping_address,reference,payment_days,date,delivery_date,currency,discount_rate,discount_value,total_sub,total_tax,total_net,seller_id,user_id) VALUES(?,1,?,?,?,?,?,?,?,0,?,?,'PEN',0,0,50,9,59,?,?)")->execute(['QA-COT-'.$suffix,$customerId,$warehouseId,$ruc,'CLIENTE QA CONVERSION','Fiscal QA','Entrega QA','REF',$today,$today,$userId,$userId]);$quotationId=(int)$pdo->lastInsertId();
 $pdo->prepare('INSERT INTO tbl_quotation_detail(quotation_id,item_id,item_name,item_description,item_unit_price,item_quantity) VALUES(?,?,?,?,?,?)')->execute([$quotationId,$productId,'ARTICULO QA CONVERSION','Temporal',25,2]);
 $pdo->prepare("INSERT INTO tbl_sales_order(number,status,quotation_id,customer_id,warehouse_id,ruc,customer_name,address,shipping_address,issue_date,delivery_date,currency,total_sub,total_tax,total_net,user_id) VALUES(?,'Anulada',?,?,?,?,?,?,?,?,?,'PEN',50,9,59,?)")->execute(['QA-OV-OLD-'.$suffix,$quotationId,$customerId,$warehouseId,$ruc,'CLIENTE QA CONVERSION','Fiscal QA','Entrega QA',$today,$today,$userId]);$cancelledOrderId=(int)$pdo->lastInsertId();
 register_shutdown_function(function()use(&$pdo,&$quotationId,&$productId,&$customerId,$cancelledOrderId){$failed=null;try{$statement=$pdo->prepare("SELECT id,status,address,shipping_address,total_net FROM tbl_sales_order WHERE quotation_id=? AND id<>?");$statement->execute([$quotationId,$cancelledOrderId]);$new=$statement->fetch();if(!$new||$new['status']!=='Pendiente'||$new['address']!=='Fiscal QA'||$new['shipping_address']!=='Entrega QA'||abs((float)$new['total_net']-59)>0.01)$failed='La reconversion no copio cabecera, detalle o estado.';else{$details=$pdo->prepare('SELECT item_id,item_quantity,item_unit_price FROM tbl_sales_order_detail WHERE sales_order_id=?');$details->execute([$new['id']]);$line=$details->fetch();if(!$line||(int)$line['item_id']!==$productId||(int)$line['item_quantity']!==2||abs((float)$line['item_unit_price']-25)>0.01)$failed='La reconversion no copio el detalle.';}}catch(Throwable $e){$failed=$e->getMessage();}try{cleanupQuotationConversion($pdo,$quotationId,$productId,$customerId);}catch(Throwable $cleanup){if(!$failed)$failed='Limpieza: '.$cleanup->getMessage();}if($failed){fwrite(STDERR,"FAIL quotation conversion lifecycle: {$failed}\n");exit(1);}echo "PASS quotation conversion after cancelled order lifecycle\n";});
 $_SERVER['REQUEST_METHOD']='POST';$_SERVER['SCRIPT_NAME']='/modules/ventas/ordenes.php';$_POST=['action'=>'convert_from_quotation','quotation_id'=>$quotationId,'warehouse_id'=>$warehouseId];chdir($root.'/modules/ventas');include 'ordenes.php';
}catch(Throwable $e){cleanupQuotationConversion($pdo,$quotationId,$productId,$customerId);fwrite(STDERR,'FAIL quotation conversion setup: '.$e->getMessage().PHP_EOL);exit(1);}
